static int Subtotal(int qty, int price)
{
    return qty * price;
}
static int WithService(int s)
{
    return s + s / 10;
}
static void Show(int qty, int price)
{
    Console.WriteLine("المجموع: " + WithService(Subtotal(qty, price)));
}
static void Main()
